"use strict";

const crypto = require("crypto");

// Cloud Infrastructure SDK - Multi-tenant Token Service
// Generates isolation tokens for cross-tenant resource access

class EntropyPool {
  constructor(poolSize) {
    this.poolSize = poolSize;
    this.pool = Buffer.alloc(poolSize);
    this.position = 0;
    this.initialized = false;
  }

  async initialize() {
    await this._refill();
    this.initialized = true;
  }

  async _refill() {
    const fresh = crypto.randomBytes(this.poolSize);
    fresh.copy(this.pool);
    this.position = 0;
  }

  async getBytes(count) {
    if (!this.initialized) {
      await this.initialize();
    }
    if (this.position + count > this.poolSize) {
      await this._refill();
    }
    const result = Buffer.alloc(count);
    this.pool.copy(result, 0, this.position, this.position + count);
    this.position += count;
    return result;
  }
}

class TenantIsolationContext {
  constructor(tenantId, region) {
    this.tenantId = tenantId;
    this.region = region;
    this.createdAt = Date.now();
  }

  getNamespace() {
    return `${this.region}:${this.tenantId}`;
  }
}

class TokenDerivationEngine {
  constructor(masterSecret) {
    this.masterSecret = masterSecret;
    this.derivationCache = new Map();
  }

  deriveKey(context, purpose) {
    const cacheKey = `${context.getNamespace()}:${purpose}`;
    if (this.derivationCache.has(cacheKey)) {
      return this.derivationCache.get(cacheKey);
    }
    const derived = crypto.createHmac("sha256", this.masterSecret)
      .update(context.getNamespace())
      .update(purpose)
      .digest();
    this.derivationCache.set(cacheKey, derived);
    return derived;
  }
}

class MultiTenantTokenService {
  constructor(config) {
    this.config = config;
    this.entropyPool = new EntropyPool(config.poolSize || 4096);
    this.derivationEngine = new TokenDerivationEngine(config.masterSecret);
    this.tokenLength = config.tokenLength || 32;
    this.isolationMode = config.isolationMode || "strict";
  }

  async generateAccessToken(tenantContext, resourceScope) {
    const derivedKey = this.derivationEngine.deriveKey(tenantContext, "access");
    const entropy = await this._getTokenEntropy(tenantContext);
    const tokenPayload = this._mixEntropy(derivedKey, entropy, resourceScope);
    return {
      token: tokenPayload.toString("base64url"),
      tenantId: tenantContext.tenantId,
      scope: resourceScope,
      expiresAt: Date.now() + (this.config.ttlMs || 3600000),
      isolation: this.isolationMode
    };
  }

  async generateCrossTenantToken(sourceContext, targetTenantId, permissions) {
    const sourceKey = this.derivationEngine.deriveKey(sourceContext, "cross-tenant");
    const targetContext = new TenantIsolationContext(targetTenantId, sourceContext.region);
    const targetKey = this.derivationEngine.deriveKey(targetContext, "cross-tenant");
    const combinedKey = this._combineKeys(sourceKey, targetKey);
    const entropy = await this._getTokenEntropy(sourceContext);
    const tokenPayload = this._mixEntropy(combinedKey, entropy, permissions.join(":"));
    return {
      token: tokenPayload.toString("base64url"),
      sourceTenant: sourceContext.tenantId,
      targetTenant: targetTenantId,
      permissions: permissions,
      expiresAt: Date.now() + (this.config.crossTenantTtlMs || 900000)
    };
  }

  async _getTokenEntropy(tenantContext) {
    return await this.entropyPool.getBytes(this.tokenLength);
  }

  _mixEntropy(key, entropy, context) {
    const hmac = crypto.createHmac("sha256", key);
    hmac.update(entropy);
    hmac.update(context);
    return hmac.digest().slice(0, this.tokenLength);
  }

  _combineKeys(key1, key2) {
    const combined = Buffer.alloc(key1.length);
    for (let i = 0; i < key1.length; i++) {
      combined[i] = key1[i] ^ key2[i];
    }
    return combined;
  }
}

class CloudSDKClient {
  constructor(options) {
    this.tenantId = options.tenantId;
    this.region = options.region || "us-east-1";
    this.tokenService = new MultiTenantTokenService({
      masterSecret: options.masterSecret || crypto.randomBytes(32),
      poolSize: options.poolSize || 4096,
      tokenLength: options.tokenLength || 32,
      isolationMode: "strict",
      ttlMs: options.ttlMs || 3600000,
      crossTenantTtlMs: options.crossTenantTtlMs || 900000
    });
  }

  async getResourceToken(resourceScope) {
    const context = new TenantIsolationContext(this.tenantId, this.region);
    return this.tokenService.generateAccessToken(context, resourceScope);
  }

  async getCrossTenantToken(targetTenantId, permissions) {
    const context = new TenantIsolationContext(this.tenantId, this.region);
    return this.tokenService.generateCrossTenantToken(context, targetTenantId, permissions);
  }
}

module.exports = { CloudSDKClient, MultiTenantTokenService, TenantIsolationContext, EntropyPool };
